1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type ClaimStep = {
19	  op: "claim";
20	  policy: number;
21	  incident: { cause: string; damages: Damage[] };
22	};
23	
24	export type Step = QuoteStep | ClaimStep;
25	
26	export type Customer = {
27	  yearsWithMHPCO: number;
28	};
29	
30	export type Scenario = {
31	  customer: Customer;
32	  steps: Step[];
33	};
34	
35	export type ScenarioResults = {
36	  results: unknown[];
37	};
38	
39	const PROCESSING_FEE = 5;
40	const FIRST_INSURANCE_SURCHARGE = 0.1;
41	const CURSE_SURCHARGE = 0.5;
42	const HIGH_ENCHANTMENT_THRESHOLD = 5;
43	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
44	const LOYALTY_YEARS_THRESHOLD = 2;
45	const LOYALTY_DISCOUNT = 0.2;
46	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
47	const DEDUCTIBLE = 100;
48	const CAP_MULTIPLIER = 2;
49	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
50	const HIGH_ENCHANTMENT_REIMBURSEMENT = 0.5;
51	const DEFAULT_REIMBURSEMENT_RATE = 1;
52	
53	const INSURANCE_VALUES: Record<string, number> = {
54	  sword: 1000,
55	  amulet: 600,
56	  staff: 800,
57	  potion: 400,
58	  rune: 250,
59	  moonstone: 250,
60	};
61	
62	const ITEM_BASE_PREMIUMS: Record<string, number> = {
63	  sword: 100,
64	  amulet: 60,
65	  staff: 80,
66	  potion: 40,
67	  rune: 25,
68	  moonstone: 25,
69	};
70	
71	/** Premiums round up: the MHPCO's favour is the higher number. */
72	const roundPremiumInMHPCOsFavour = (premium: number): number =>
73	  Math.ceil(premium);
74	
75	/** Payouts round down: the MHPCO's favour is the lower number. */
76	const roundPayoutInMHPCOsFavour = (payout: number): number =>
77	  Math.floor(payout);
78	
79	const BLOCK_SIZE = 3;
80	const BLOCK_BASE_PREMIUM = 60;
81	
82	const countByType = (items: Item[]): Map<string, number> => {
83	  const counts = new Map<string, number>();
84	  for (const item of items) {
85	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
86	  }
87	  return counts;
88	};
89	
90	const basePremiumForGroup = (type: string, count: number): number =>
91	  count === BLOCK_SIZE
92	    ? BLOCK_BASE_PREMIUM
93	    : count * ITEM_BASE_PREMIUMS[type];
94	
95	const policyBasePremium = (items: Item[]): number =>
96	  [...countByType(items)].reduce(
97	    (total, [type, count]) => total + basePremiumForGroup(type, count),
98	    0,
99	  );
100	
101	type SurchargeRule = {
102	  appliesTo: (item: Item) => boolean;
103	  rate: number;
104	};
105	
106	const SURCHARGE_RULES: SurchargeRule[] = [
107	  {
108	    appliesTo: (item) => item.cursed === true,
109	    rate: CURSE_SURCHARGE,
110	  },
111	  {
112	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
113	    rate: HIGH_ENCHANTMENT_SURCHARGE,
114	  },
115	];
116	
117	const itemSurcharge = (item: Item): number => {
118	  const itemBasePremium = ITEM_BASE_PREMIUMS[item.type];
119	  return SURCHARGE_RULES.filter((rule) => rule.appliesTo(item)).reduce(
120	    (surcharge, rule) => surcharge + itemBasePremium * rule.rate,
121	    0,
122	  );
123	};
124	
125	const sumItemSurcharges = (items: Item[]): number =>
126	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
127	
128	type PolicyContext = {
129	  customer: Customer;
130	  isFollowUpContract: boolean;
131	};
132	
133	type PolicyModifierRule = {
134	  appliesTo: (context: PolicyContext) => boolean;
135	  /** Signed rate applied to the policy base premium: positive adds, negative discounts. */
136	  rate: number;
137	};
138	
139	const POLICY_MODIFIER_RULES: PolicyModifierRule[] = [
140	  {
141	    appliesTo: () => true,
142	    rate: FIRST_INSURANCE_SURCHARGE,
143	  },
144	  {
145	    appliesTo: ({ customer }) =>
146	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
147	    rate: -LOYALTY_DISCOUNT,
148	  },
149	  {
150	    appliesTo: ({ isFollowUpContract }) => isFollowUpContract,
151	    rate: -FOLLOW_UP_CONTRACT_DISCOUNT,
152	  },
153	];
154	
155	const sumPolicyModifiers = (
156	  basePremium: number,
157	  context: PolicyContext,
158	): number =>
159	  POLICY_MODIFIER_RULES.filter((rule) => rule.appliesTo(context)).reduce(
160	    (total, rule) => total + basePremium * rule.rate,
161	    0,
162	  );
163	
164	const quotePremium = (items: Item[], context: PolicyContext): number => {
165	  const basePremium = policyBasePremium(items);
166	  return roundPremiumInMHPCOsFavour(
167	    basePremium +
168	      sumItemSurcharges(items) +
169	      sumPolicyModifiers(basePremium, context) +
170	      PROCESSING_FEE,
171	  );
172	};
173	
174	const insuranceSum = (items: Item[]): number =>
175	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
176	
177	/**
178	 * The fraction of a damage amount the policy covers, before the deductible.
179	 *
180	 * The spec also states that dragon-material items are "fully reimbursed". That
181	 * clause is not listed here because full reimbursement is already the default
182	 * rate: in every spec example the two coincide, so no test can tell an explicit
183	 * dragon clause apart from this default. Adding one would be untested code.
184	 * A dragon clause only becomes observable if a future rule reduces the default
185	 * below 1 for some item a dragon-material item could also match.
186	 */
187	const reimbursementRateFor = (item: Item | undefined): number =>
188	  (item?.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD
189	    ? HIGH_ENCHANTMENT_REIMBURSEMENT
190	    : DEFAULT_REIMBURSEMENT_RATE;
191	
192	/** What the policy covers for one damaged item, before the deductible. */
193	const coveredAmountFor = (damage: Damage, insuredItems: Item[]): number => {
194	  const item = insuredItems.find(
195	    (candidate) => candidate.type === damage.itemType,
196	  );
197	  return damage.amount * reimbursementRateFor(item);
198	};
199	
200	/**
201	 * What the claim asks for, before the policy's remaining cap is applied.
202	 * The deductible is withheld once per damaged item.
203	 */
204	const desiredPayout = (damages: Damage[], insuredItems: Item[]): number =>
205	  damages.reduce(
206	    (sum, damage) => sum + coveredAmountFor(damage, insuredItems) - DEDUCTIBLE,
207	    0,
208	  );
209	
210	/**
211	 * Tracks how much cover each policy has left. A policy is identified by the
212	 * step index of the quote that created it, which is how claims refer to it.
213	 */
214	type PolicyLedger = {
215	  open: (policyId: number, items: Item[]) => void;
216	  insuredItems: (policyId: number) => Item[];
217	  /** Pays out at most the policy's remaining cap. */
218	  drawDown: (policyId: number, desiredPayout: number) => ClaimResult;
219	};
220	
221	const createPolicyLedger = (): PolicyLedger => {
222	  const remainingCaps = new Map<number, number>();
223	  const itemsByPolicy = new Map<number, Item[]>();
224	
225	  return {
226	    open: (policyId, items) => {
227	      remainingCaps.set(policyId, insuranceSum(items) * CAP_MULTIPLIER);
228	      itemsByPolicy.set(policyId, items);
229	    },
230	
231	    insuredItems: (policyId) => itemsByPolicy.get(policyId) ?? [],
232	
233	    drawDown: (policyId, desiredPayout) => {
234	      const cap = remainingCaps.get(policyId) ?? 0;
235	      const payout = Math.min(roundPayoutInMHPCOsFavour(desiredPayout), cap);
236	      const remainingCap = cap - payout;
237	      remainingCaps.set(policyId, remainingCap);
238	      return { payout, remainingCap };
239	    },
240	  };
241	};
242	
243	type QuoteResult = { premium: number };
244	type ClaimResult = { payout: number; remainingCap: number };
245	
246	const isKnownItemType = (type: string): boolean =>
247	  Object.hasOwn(ITEM_BASE_PREMIUMS, type);
248	
249	const processQuote = (
250	  step: QuoteStep,
251	  policyId: number,
252	  scenario: Scenario,
253	  ledger: PolicyLedger,
254	): QuoteResult => {
255	  for (const item of step.items) {
256	    if (!isKnownItemType(item.type)) {
257	      throw new Error(`unknown item type: ${item.type}`);
258	    }
259	  }
260	
261	  ledger.open(policyId, step.items);
262	  return {
263	    premium: quotePremium(step.items, {
264	      customer: scenario.customer,
265	      isFollowUpContract: policyId > 0,
266	    }),
267	  };
268	};
269	
270	const countDamagesByType = (damages: Damage[]): Map<string, number> =>
271	  countByType(damages.map((damage) => ({ type: damage.itemType })));
272	
273	const validateDamages = (damages: Damage[], insuredItems: Item[]): void => {
274	  for (const damage of damages) {
275	    if (damage.amount < 0) {
276	      throw new Error(`damage amount must not be negative: ${damage.amount}`);
277	    }
278	  }
279	
280	  const insuredCounts = countByType(insuredItems);
281	  for (const [type, damagedCount] of countDamagesByType(damages)) {
282	    if (damagedCount > (insuredCounts.get(type) ?? 0)) {
283	      throw new Error(`more damages than insured items of type: ${type}`);
284	    }
285	  }
286	};
287	
288	const processClaim = (step: ClaimStep, ledger: PolicyLedger): ClaimResult => {
289	  const insuredItems = ledger.insuredItems(step.policy);
290	  validateDamages(step.incident.damages, insuredItems);
291	  return ledger.drawDown(
292	    step.policy,
293	    desiredPayout(step.incident.damages, insuredItems),
294	  );
295	};
296	
297	export const runScenario = (scenario: Scenario): ScenarioResults => {
298	  const ledger = createPolicyLedger();
299	
300	  const results = scenario.steps.map((step, index) =>
301	    step.op === "quote"
302	      ? processQuote(step, index, scenario, ledger)
303	      : processClaim(step, ledger),
304	  );
305	
306	  return { results };
307	};
